  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  // Detect 9:16 aspect ratio or portrait screens to adjust sizing automatically
  const isPortrait = width < height;

  // Resolve background color with transparency support
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Calculate timing allocation for Intro vs Schedule
  const introFrames = showIntro ? introDuration * fps : 0;
  const scheduleFrames = Math.max(0, durationInFrames - introFrames);

  // Use the schedule list if provided, otherwise fallback to single items
  const activeSchedule = schedule && schedule.length > 0 
    ? schedule 
    : [{ timestamp, drillName }];

  // Allocate remaining duration equally among all schedule items
  const itemDuration = scheduleFrames / activeSchedule.length;

  // Smooth entrance/exit transitions scaled down to fit item duration
  const transitionFrames = Math.min(20, itemDuration * 0.15);

  // Dynamic layout metrics optimized for 9:16 vertical video & standard formats
  const responsiveScale = isPortrait ? 0.75 : 1.0;
  const adjustedBannerScale = bannerScale * responsiveScale;

  // Double thickness styling preserved
  const bannerHeight = (isPortrait ? 156 : 210) * adjustedBannerScale;
  const greenWidth = width * (isPortrait ? 0.35 : 0.38) * bannerScale;
  
  const containerLeft = isPortrait ? width * 0.04 : width * 0.08;

  // Intro Card Animation States
  const introProgress = showIntro
